#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353LL;

long long modPow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long nCr(int a, int b, const vector<long long>& fact, const vector<long long>& invFact) {
    return (((fact[b] * invFact[a]) % MOD) * invFact[b - a]) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    long long lmao;
    cin >> N >> lmao;
    if (lmao >= N) {
        cout << 0 << "\n";
    } else {
        int K = (int) lmao;
        int C = N - K;
        vector<long long> factorials(200001);
        vector<long long> invFactorials(200001);
        factorials[0] = 1;
        invFactorials[0] = 1;
        for (int i = 1; i <= 200000; i++) {
            factorials[i] = (factorials[i - 1] * i) % MOD;
            invFactorials[i] = modPow(factorials[i], MOD - 2, MOD);
        }
        long long res = modPow(C, N, MOD);
        for (int e = 1; e < C; e++) {
            long long temp = modPow(C - e, N, MOD);
            temp = (temp * nCr(e, C, factorials, invFactorials)) % MOD;
            if (e % 2 == 1)
                res = (res - temp + MOD) % MOD;
            else
                res = (res + temp) % MOD;
        }
        res = (res * nCr(C, N, factorials, invFactorials)) % MOD;
        if (K > 0)
            res = (2 * res) % MOD;
        cout << res << "\n";
    }
    return 0;
}

